{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The activity would have to include unstructured outdoor play unless weather makes outdoor activity difficult to carry out reasonably.",
      "rationale": "Conveys the required unstructured outdoor play and the weather exception for reasonably carrying out outdoor activity."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Time when a student is allowed to use an electronic device, and time in physical education class, would not count.",
      "rationale": "Expressly excludes time when electronic-device use is permitted from the physical activity requirement."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Time when a student is allowed to use an electronic device, and time in physical education class, would not count.",
      "rationale": "Expressly excludes physical education class time from the physical activity requirement."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "A student could be denied participation for violating a school or district discipline policy or code of conduct, for violent or threatening behavior, or for other behavior that significantly disrupts other students’ participation. A teacher or administrator could remove the student from a physical activity period and could assign alternative lessons or activities, including physical activities, to improve the student’s behavior.",
      "rationale": "Conveys denial or removal, the authorized educators, and most misconduct grounds. However, it omits the express ground of behavior significantly impairing other students’ ability to receive the benefits of the required activity, describing only disruption of participation."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "A teacher or administrator could remove the student from a physical activity period and could assign alternative lessons or activities, including physical activities, to improve the student’s behavior.",
      "rationale": "Conveys educators’ authority to assign alternative work or activities, including physical activities, to the excluded student for behavioral improvement."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "States the effective-date trigger accurately."
    }
  ]
}
